/**
 * FOOD PILOT — STORE.JS
 * Gestion d'état centralisée via localStorage
 */

const Store = {
  data: {
    menu: [],
    orders: [],
    tables: [],
    reservations: [],
    cart: []
  },

  init() {
    this.loadData();
    if (!localStorage.getItem('foodpilot_initialized_v2')) {
      this.seedData();
      localStorage.setItem('foodpilot_initialized_v2', 'true');
    }
    
    // Écouter les changements inter-onglets
    window.addEventListener('storage', (e) => {
      if (e.key === 'foodpilot_data') {
        this.loadData();
        this.notifySubscribers();
      }
    });
  },

  subscribers: [],
  subscribe(callback) {
    this.subscribers.push(callback);
  },
  notifySubscribers() {
    this.subscribers.forEach(cb => cb(this.data));
  },

  loadData() {
    const raw = localStorage.getItem('foodpilot_data');
    if (raw) {
      this.data = JSON.parse(raw);
    }
  },

  saveData() {
    localStorage.setItem('foodpilot_data', JSON.stringify(this.data));
    this.notifySubscribers();
  },

  seedData() {
    this.data.menu = [
      { id: 'm1', name: 'Thiéboudienne ', price: 1500, category: 'Plats', image: 'data:image/jpeg;base64,', prepTime: 25 },
      { id: 'm2', name: 'Yassa Poulet', price: 1000, category: 'Plats', image: 'data:image/jpeg;base64,', prepTime: 15 },
      { id: 'm3', name: 'Mafé de Bœuf', price: 1500, category: 'Plats', image: 'data:image/jpeg;base64,', prepTime: 20 },
      { id: 'm4', name: 'Dibi d\'Agneau', price: 4000, category: 'Grillades', image: 'data:image/jpeg;base64,', prepTime: 30 },
      { id: 'm5', name: 'Salade de fruit', price: 1000, category: 'Entrées', image: 'data:image/jpeg;base64,', prepTime: 10 },
      { id: 'm6', name: 'Pastels au thon', price: 1000, category: 'Entrées', image: 'data:image/jpeg;base64,', prepTime: 10 },
      { id: 'm7', name: 'Bissap', price: 1000, category: 'Boissons', image: 'data:image/jpeg;base64,', prepTime: 5 },
      { id: 'm8', name: 'Bouye', price: 1000, category: 'Boissons', image: 'data:image/jpeg;base64,', prepTime: 5 },
      { id: 'm9', name: 'Thiakry', price: 1000, category: 'Desserts', image: 'data:image/jpeg;base64,', prepTime: 10 }
    ];

    this.data.tables = Array.from({length: 15}, (_, i) => ({
      id: `T${i+1}`,
      name: `Table ${String(i+1).padStart(2, '0')}`,
      status: 'libre' // libre, occupee
    }));

    this.data.orders = [
      {
        id: 'CMD-1001',
        table: 'T4',
        type: 'sur_place',
        status: 'en_attente', // en_attente, en_preparation, en_cuisson, prete, servie, payee, annulee
        items: [{ itemId: 'm1', quantity: 2, note: 'Sans piment' }, { itemId: 'm2', quantity: 1 }],
        total: 18000,
        createdAt: new Date(Date.now() - 10 * 60000).toISOString()
      },
      {
        id: 'CMD-1002',
        table: 'T7',
        type: 'sur_place',
        status: 'en_preparation',
        items: [{ itemId: 'm1', quantity: 3 }, { itemId: 'm5', quantity: 1, note: 'Sans coriandre' }],
        total: 22000,
        createdAt: new Date(Date.now() - 25 * 60000).toISOString()
      },
      {
        id: 'CMD-1003',
        type: 'livraison',
        status: 'en_cuisson',
        clientName: 'Diallo',
        items: [{ itemId: 'm3', quantity: 1 }, { itemId: 'm4', quantity: 2 }],
        total: 21500,
        createdAt: new Date(Date.now() - 40 * 60000).toISOString()
      }
    ];
    
    this.data.tables[3].status = 'occupee'; // T4
    this.data.tables[6].status = 'occupee'; // T7

    this.saveData();
  },

  // === ACTIONS CRUD ===

  addOrder(orderData) {
    const newOrder = {
      id: `CMD-${Date.now().toString().slice(-4)}`,
      status: 'en_attente',
      createdAt: new Date().toISOString(),
      lastUpdate: new Date().toISOString(),
      ...orderData
    };
    this.data.orders.unshift(newOrder);
    
    if (newOrder.table) {
      const table = this.data.tables.find(t => t.id === newOrder.table);
      if (table) table.status = 'occupee';
    }
    
    this.saveData();
    return newOrder;
  },

  addReservation(resaData) {
    const newResa = {
      id: `RES-${Date.now().toString().slice(-4)}`,
      createdAt: new Date().toISOString(),
      status: 'confirmée',
      ...resaData
    };
    this.data.reservations.unshift(newResa);
    this.saveData();
    return newResa;
  },

  updateOrderStatus(orderId, newStatus) {
    const order = this.data.orders.find(o => o.id === orderId);
    if (!order) return;

    // Logique stricte des états
    const steps = ['en_attente', 'en_preparation', 'en_cuisson', 'prete', 'en_livraison', 'livree', 'servie', 'payee'];
    const currentIndex = steps.indexOf(order.status);
    const newIndex = steps.indexOf(newStatus);
    
    // On ne peut annuler que si c'est en attente
    if (newStatus === 'annulee' && order.status !== 'en_attente') return;
    
    // On ne peut pas reculer dans les étapes (sauf pour annuler, géré juste avant)
    if (newStatus !== 'annulee' && newIndex !== -1 && currentIndex !== -1 && newIndex < currentIndex) {
      console.warn(`Transition impossible : de ${order.status} à ${newStatus}`);
      return; 
    }

    order.status = newStatus;
    order.lastUpdate = new Date().toISOString();

    if (newStatus === 'payee' || newStatus === 'annulee') {
      if (order.table && order.table !== 'Client') {
        const table = this.data.tables.find(t => t.id === order.table);
        if (table) table.status = 'libre';
      }
    }
    this.saveData();
  },

  modifyOrderItems(orderId, newItems, newTotal) {
    const order = this.data.orders.find(o => o.id === orderId);
    if (order && order.status === 'en_attente') {
      order.items = newItems;
      order.total = newTotal;
      this.saveData();
      return true;
    }
    return false;
  },

  cancelOrder(orderId) {
    this.updateOrderStatus(orderId, 'annulee');
  },
  
  addToCart(item) {
    const existing = this.data.cart.find(i => i.id === item.id);
    if (existing) {
      existing.quantity += item.quantity || 1;
    } else {
      this.data.cart.push({ ...item, quantity: item.quantity || 1 });
    }
    this.saveData();
  },
  
  removeFromCart(itemId) {
    this.data.cart = this.data.cart.filter(i => i.id !== itemId);
    this.saveData();
  },
  
  clearCart() {
    this.data.cart = [];
    this.saveData();
  },
  
  getCartTotal() {
    return this.data.cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  }
};

// Initialisation synchrone au chargement
Store.init();
window.Store = Store;
